  const publishing=document.createElement('details');publishing.id='draft-publishing';publishing.className='production-panel';publishing.open=true;publishing.innerHTML=`<summary>保存到剪映</summary><div class="production-actions"><label>剪映草稿根目录<input id="draft-publish-directory" placeholder="载入后默认使用当前草稿所在根目录"></label><button id="draft-publish-pick">选择目录</button><label>保存方式<select id="draft-publish-mode"><option value="new">新建草稿</option><option value="overwrite">干净覆盖当前草稿</option></select></label><label id="draft-publish-name-label">新草稿名称<input id="draft-publish-name" maxlength="100"></label></div><p id="draft-publish-note">直接保存到选定目录，新建模式保留原草稿。</p>`;$('existing-status').after(publishing);
  const publishChoice=()=>({publish:{mode:$('draft-publish-mode').value,directory:$('draft-publish-directory').value.trim(),name:$('draft-publish-name').value.trim()}});
  function renderPublishing(){const overwrite=$('draft-publish-mode').value==='overwrite';$('draft-publish-name-label').hidden=overwrite;$('draft-publish-directory').readOnly=overwrite;$('draft-publish-pick').disabled=overwrite;$('draft-publish-note').textContent=overwrite?'完整替换本次载入的草稿目录。保存前自动在原目录外备份；请先在剪映保存并关闭该草稿。':'直接保存新草稿到选定目录，原草稿保留。';$('existing-save').textContent=overwrite?'干净覆盖当前草稿':'保存到剪映';}
  $('draft-publish-mode').onchange=()=>{if($('draft-publish-mode').value==='overwrite'&&session)$('draft-publish-directory').value=session.sourcePath.replace(/\\/g,'/').split('/').slice(0,-2).join('/');renderPublishing();};
  $('draft-publish-pick').onclick=()=>work(async()=>{const result=await api('/api/draft-publishing/pick-directory',{directory:$('draft-publish-directory').value});if(result.directory)$('draft-publish-directory').value=result.directory;});
  // Keep pending suggestions above lengthy controls so applying a preview is easy.
  $('existing-draft-page').querySelector('.existing-sidebar').prepend($('existing-proposal'));
  let session=null,cues=[],history=[],future=[],undoTracks={},review=null,proposal=null,busy=false,states={},chat=[],log=[],revision=null,baseline='',activeTrack=null,progressSaved=false,stylePatch={},styleInfo=null,currentCue=null,recoveryPreview=null;
  let autoSaveTimer=null,autoSavePaused=false,progressSaving=null,recoveryLoad=false;
  window.workshopActivity ||= {};
  window.workshopActivity.existingDraft=()=>Boolean(busy||progressSaving||(session&&progressFingerprint()!==baseline));
  const status=text=>$('existing-status').textContent=text;
  const selected=()=>Number($('existing-track').value);
  const original=()=>session?.tracks.find(t=>t.index===selected())?.cues||[];
  function record(label){log.push(new Date().toLocaleTimeString()+' · '+label);log=log.slice(-100);renderLog();}
  function renderLog(){$('existing-edit-log').replaceChildren();log.slice().reverse().forEach(text=>{const li=document.createElement('li');li.textContent=text;$('existing-edit-log').append(li);});}
  function capture(){return {texts:cues.map(c=>c.text),manuscript:$('existing-manuscript').value,mode:$('existing-mode').value,chatHistory:chat,editLog:log,stylePatch};}
  function store(){if(session)states[selected()]=structuredClone(capture());}
  function fingerprint(){return JSON.stringify({track:selected(),...capture()});}
  function progressFingerprint(){store();return JSON.stringify(states);}
  function progressStatus(){$('existing-progress-status').textContent=progressFingerprint()===baseline?(progressSaved?'进度已保存':'尚未编辑'):'进度未保存';scheduleProgress();}
  function scheduleProgress(){clearTimeout(autoSaveTimer);if(!session||autoSavePaused||!$('existing-auto-save').checked||progressFingerprint()===baseline)return;autoSaveTimer=setTimeout(async()=>{if(busy){scheduleProgress();return;}try{await saveProgress();}catch(e){autoSavePaused=true;$('existing-reload-recover').hidden=false;$('existing-source').open=true;$('existing-progress-status').textContent='自动保存暂停，进度未保存';status('自动保存未完成：'+e.message+'；本页编辑仍保留，可修正后手动保存或备份后重新载入');}},5000);}
  function invalidate(){review=null;$('existing-review').replaceChildren();$('existing-apply').disabled=true;proposal=null;$('existing-proposal').hidden=true;recoveryPreview=null;$('existing-backup-apply').disabled=true;$('existing-backup-changes').replaceChildren();if($('existing-backup-status').textContent==='预览完成，尚未恢复')$('existing-backup-status').textContent='编辑已变化，请重新预览恢复';}
  function snapshot(){return structuredClone({cues,chat,log,stylePatch,manuscript:$('existing-manuscript').value,mode:$('existing-mode').value});}
  function remember(){history.push(snapshot());if(history.length>30)history.shift();future=[];}
  function renderChat(){$('existing-chat-history').replaceChildren();chat.slice(-12).forEach(h=>{const p=document.createElement('p');p.className='assistant-message';p.dataset.role=h.role;p.textContent=h.text;$('existing-chat-history').append(p);});}
  function refreshButtons(){$('existing-undo').disabled=busy||!history.length;$('existing-redo').disabled=busy||!future.length;$('existing-apply').disabled=busy||!review;$('existing-backup-apply').disabled=busy||!recoveryPreview;$('existing-proposal-apply').disabled=busy||(!proposal?.changes.length&&!proposal?.styleChanges?.length);}
  function qualityIssues(){const found=cues.map(c=>{const length=Array.from(c.text.trim().replace(/\s/g,'')).length,duration=c.end-c.start,result=[];if(!length)result.push('空字幕，输出前需补全');if(length>32)result.push('字幕较长');if(duration<=0)result.push('显示时间无效');else if(length/duration>12)result.push('显示较快');return result;});const order=cues.map((c,i)=>({start:c.start,end:c.end,i})).sort((a,b)=>a.start-b.start);let previous=null;for(const item of order){if(previous&&item.start<previous.end){if(!found[item.i].includes('时间重叠'))found[item.i].push('时间重叠');if(!found[previous.i].includes('时间重叠'))found[previous.i].push('时间重叠');}if(!previous||item.end>previous.end)previous=item;}return found;}
  function renderQuality(issues){const count=issues.filter(row=>row.length).length;$('existing-quality-count').textContent=`· ${count} 条待核对`;const host=$('existing-quality-results');host.replaceChildren();issues.forEach((items,i)=>{if(!items.length)return;const button=document.createElement('button');button.type='button';button.textContent=`第 ${i+1} 条 · ${items.join('，')}`;button.onclick=()=>locate(i,true);host.append(button);});if(!count){const note=document.createElement('p');note.textContent='未发现上述问题，内容准确性仍请结合配音核对';host.append(note);}}
  function render(){const originals=original(),query=$('existing-search').value.trim().toLocaleLowerCase(),only=$('existing-only-changes').checked,issues=qualityIssues();renderQuality(issues);const host=$('existing-cues');host.replaceChildren();let shown=0,changed=0;
    cues.forEach((cue,i)=>{const before=originals[i].text,isChanged=before!==cue.text;if(isChanged)changed++;if(only&&!isChanged||$('existing-only-issues').checked&&!issues[i].length||query&&!`${before}\n${cue.text}`.toLocaleLowerCase().includes(query))return;shown++;
      const row=document.createElement('div');row.className='existing-cue-row';row.dataset.changed=String(isChanged);row.dataset.cueIndex=i;row.dataset.active=String(currentCue===i);
      const time=document.createElement('div');time.className='existing-cue-time';time.textContent=`第 ${i+1} 条\n${cue.start.toFixed(2)}–${cue.end.toFixed(2)} 秒${isChanged?'\n已修改':''}`;
      const source=document.createElement('p');source.className='existing-original';source.textContent=before;
      const input=document.createElement('textarea');input.rows=2;input.maxLength=2000;input.value=cue.text;input.dataset.cueIndex=i;input.setAttribute('aria-label',`第${i+1}条修改结果`);
      input.onfocus=()=>{currentCue=i;markLocation();};let remembered=false;
      input.oninput=()=>{if(cues[i].text===input.value)return;if(!remembered){remember();remembered=true;record(`手动修改第 ${i+1} 条`);}cues[i].text=input.value;invalidate();row.dataset.changed=String(before!==input.value);renderQuality(qualityIssues());refreshButtons();progressStatus();};
      input.onchange=()=>{if(!remembered)return;render();progressStatus();status('改动已进入本页，可撤销');};row.append(time,source,input);host.append(row);
    });
    if(!shown){const empty=document.createElement('p');empty.textContent='没有符合筛选条件的字幕';host.append(empty);}
    $('existing-count').textContent=`${cues.length} 条字幕 · ${changed} 条改动 · 显示 ${shown} 条`;markLocation();refreshButtons();
  }
  function request(){if(!session)throw new Error('请先载入草稿');return {sessionId:session.sessionId,trackIndex:selected(),sourcePath:session.sourcePath,sourceHash:session.sourceHash};}
  async function work(fn){if(busy)return;busy=true;const controls=[...$('existing-draft-page').querySelectorAll('button,input,textarea,select')],disabled=controls.map(c=>c.disabled);controls.forEach(c=>c.disabled=true);try{await fn();}catch(e){status(e.message);if(session&&progressFingerprint()!==baseline){$('existing-reload-recover').hidden=false;}}finally{controls.forEach((c,i)=>c.disabled=disabled[i]);busy=false;refreshButtons();refreshVideoButtons();renderPublishing();}}
  function adopt(trackIndex){const state=states[trackIndex],track=session.tracks.find(t=>t.index===trackIndex);activeTrack=trackIndex;$('existing-track').value=trackIndex;cues=structuredClone(track.cues);if(state)cues.forEach((c,i)=>c.text=state.texts[i]);$('existing-manuscript').value=state?.manuscript||'';$('existing-mode').value=state?.mode||'auto';chat=structuredClone(state?.chatHistory||[]);log=[...(state?.editLog||[])];stylePatch=structuredClone(state?.stylePatch||{});history=undoTracks[trackIndex]?.history||[];future=undoTracks[trackIndex]?.future||[];currentCue=null;invalidate();$('existing-backups').replaceChildren(new Option('刷新后选择备份',''));$('existing-backup-status').textContent='';renderChat();renderLog();render();}
  async function models(){const settings=await api('/api/assistant/settings');$('existing-model').replaceChildren();settings.models.forEach(m=>{const option=document.createElement('option');option.value=m.id;option.textContent=m.name;$('existing-model').append(option);});if(!settings.models.length){const option=document.createElement('option');option.textContent='请先配置聊天模型';option.value='';$('existing-model').append(option);}else $('existing-model').value=settings.activeModelId;}
  $('existing-back').onclick=()=>work(async()=>{if(session&&progressFingerprint()!==baseline)await saveProgress();$('nav-tools').click();});
  $('existing-pick').onclick=()=>work(async()=>{const r=await api('/api/existing-draft/pick',{});if(r.path)$('existing-path').value=r.path;});
  async function loadDraft(){if(session&&progressFingerprint()!==baseline&&!recoveryLoad){status('先保存当前草稿进度…');await saveProgress();}status('正在载入草稿…');const r=await api('/api/existing-draft/load',{path:$('existing-path').value,installPath:$('existing-install').value,pythonPath:$('existing-python').value});session=r;resetBilingual();states={};undoTracks={};history=[];future=[];revision=r.progress?.revision||null;autoSavePaused=false;recoveryLoad=false;$('existing-reload-recover').hidden=true;
    progressSaved=!!(r.progress&&!r.progressStale);
    if(progressSaved)r.progress.tracks.forEach(s=>{if(!r.tracks.some(t=>t.index===s.trackIndex&&t.cues.length===s.texts?.length))return;const value={...s,stylePatch:s.stylePatch||{}};delete value.trackIndex;states[s.trackIndex]=value;});
    $('existing-track').replaceChildren();r.tracks.forEach(t=>{const option=document.createElement('option');option.value=t.index;option.textContent=t.name+' · '+t.cues.length+' 条';$('existing-track').append(option);});
    const preferred=r.progress&&!r.progressStale?Object.keys(states).map(Number)[0]:undefined;adopt(preferred??r.tracks.find(t=>t.name.includes('字幕'))?.index??r.tracks[0].index);
    $('existing-editor').hidden=false;$('existing-result').replaceChildren();$('existing-source').open=false;baseline=progressFingerprint();progressStatus();await refreshStyle();await models();const publishingOptions=await api('/api/draft-publishing/options',request());$('draft-publish-directory').value=publishingOptions.directory;$('draft-publish-name').value=session.name+'·修改版';$('draft-publish-mode').value='new';renderPublishing();status(`已载入 ${r.name}${r.progressIssue?'；'+r.progressIssue:r.progressStale?'；原草稿已变化，旧进度未套用':r.progress?'；已恢复保存的编辑进度':'，可开始校对'}`);
  }
  $('existing-load').onclick=()=>work(loadDraft);
  $('existing-track').onchange=()=>work(async()=>{const next=selected();if(activeTrack!==null&&activeTrack!==next){states[activeTrack]=structuredClone(capture());undoTracks[activeTrack]={history,future};}adopt(next);progressStatus();await refreshStyle();status('已切换轨道，编辑与撤销记录保留');});
  async function restoreSnapshot(value){cues=value.cues;chat=value.chat;log=value.log;stylePatch=value.stylePatch;$('existing-manuscript').value=value.manuscript;$('existing-mode').value=value.mode;invalidate();renderChat();renderLog();render();progressStatus();await refreshStyle();}
  $('existing-undo').onclick=()=>work(async()=>{if(!history.length)return;future.push(snapshot());await restoreSnapshot(history.pop());status('已撤销上一步编辑，可重做');});
  $('existing-redo').onclick=()=>work(async()=>{if(!future.length)return;history.push(snapshot());await restoreSnapshot(future.pop());status('已重做上一步编辑');});
  function markLocation(){document.querySelectorAll('#existing-cues .existing-cue-row').forEach(row=>row.dataset.active=String(Number(row.dataset.cueIndex)===currentCue));$('existing-location').textContent=currentCue===null?'':`第 ${currentCue+1} 条 · ${cues[currentCue]?.start.toFixed(2)} 秒`;}
  function locate(index,clearFilters=false){if(!Number.isInteger(index)||index<0||index>=cues.length){status('没有对应的字幕，请检查序号或时间');return;}if(clearFilters){$('existing-search').value='';$('existing-only-changes').checked=false;$('existing-only-issues').checked=false;}currentCue=index;render();const input=$('existing-cues').querySelector(`textarea[data-cue-index="${index}"]`);if(input){input.scrollIntoView({block:'nearest'});input.focus({preventScroll:true});}else status('这条字幕被筛选隐藏，请清空筛选再定位');}
  $('existing-jump-go').onclick=()=>{const value=$('existing-jump').value.trim();let index;if(/^\d+$/.test(value))index=Number(value)-1;else if(/^\d+:\d{1,2}(?:\.\d+)?$/.test(value)){const [minutes,seconds]=value.split(':').map(Number);if(seconds>=60){status('时间秒数应小于 60');return;}const time=minutes*60+seconds;index=cues.findIndex(c=>c.end>time);if(index>=0&&cues[index].start>time)status('此处为字幕间隙，已定位下一条');}else{status('请输入字幕序号或分:秒，例如 28 或 1:20');return;}locate(index,true);};
