  async function bilingualReadTemplate(){pausePreview=null;cleanAudio=null;bilingualResult=null;$('bilingual-export').disabled=true;bilingualInfo=await api('/api/bilingual-dialogue/template',{...bilingualBase(),...(customPortraits?{portraitAssets:customPortraits}:{})});$('bilingual-audio').replaceChildren();bilingualInfo.audioClips.forEach((c,i)=>{const o=document.createElement('option');o.value=i;o.textContent=c.name+' · 轨道 '+(c.trackIndex+1);$('bilingual-audio').append(o);});$('bilingual-expressions').replaceChildren();bilingualInfo.assets.forEach(a=>{const label=document.createElement('label'),check=document.createElement('input');check.type='checkbox';check.value=a.id;check.checked=true;const alias=document.createElement('input');alias.value=a.label;alias.maxLength=100;alias.placeholder='表情与姿势，如微笑·坐姿';alias.dataset.portraitLabel=a.id;const format=document.createElement('select');format.dataset.portraitTemplate=a.id;const track=bilingualCharacters?.tracks.find(t=>t.index===Number($('bilingual-video-track').value));track?.assets.forEach(sample=>{const option=document.createElement('option');option.value=sample.segmentIndex;option.textContent='格式：'+sample.name;format.append(option);});format.value=String(a.templateSegmentIndex??Number($('bilingual-video-sample').value));const thumb=document.createElement('img');thumb.alt=a.label;thumb.className='portrait-label-thumb';thumb.src='/api/bilingual-dialogue/portrait?'+new URLSearchParams({token:bilingualInfo.previewToken,sessionId:session.sessionId,id:a.id});label.append(check,thumb,alias,format);$('bilingual-expressions').append(label);});$('bilingual-status').textContent=`找到 ${bilingualInfo.assets.length} 个同组表情，默认保留同服装与姿势；可取消不需要的表情`;}
