  function renderBilingual(result){const host=$('bilingual-rows');host.replaceChildren();result.rows.forEach((row,i)=>{const box=document.createElement('details');box.open=false;const summary=document.createElement('summary');summary.textContent=`${row.start.toFixed(2)}–${row.end.toFixed(2)} 秒 · ${row.review?'待试听核对':'已定位'} · 匹配 ${Math.round(row.confidence*100)}%`;const ja=document.createElement('p');ja.textContent='日语：'+row.japanese;const reference=document.createElement('p');reference.className='assistant-note';reference.dataset.bilingualReference=i;reference.textContent=row.referenceChinese?'百度参考译文：'+row.referenceChinese:'';reference.hidden=!row.referenceChinese;const zh=document.createElement('textarea');zh.value=row.chinese;zh.maxLength=2000;zh.dataset.bilingualText=i;zh.setAttribute('aria-label','第 '+(i+1)+' 段中文字幕');const select=document.createElement('select');select.dataset.bilingualExpression=i;result.expressions.forEach(a=>{const o=document.createElement('option');o.value=a.id;o.textContent=a.label;select.append(o);});select.value=row.expression;const label=document.createElement('label'),check=document.createElement('input');check.type='checkbox';check.dataset.bilingualReviewed=i;check.checked=!row.review;label.append(check,document.createTextNode('已核对这段日语与中文对应、时间及表情'));const reason=document.createElement('p');reason.textContent=row.reason;box.append(summary,ja,reference,zh,select,reason,label);host.append(box);});}
